# name: shorter_longest_run_preference
# description: Among pairs whose longest same-face run differs, the rate of choosing the sequence with the shorter longest run; observed above null means the model under-penalises long streaks, below means it over-penalises them.
def test_statistic(df):
    import re
    seqs = pd.unique(pd.concat([df["sequence_a"], df["sequence_b"]]))
    lr = {s: max(len(r) for r in re.findall(r"H+|T+", s)) for s in seqs}
    ra = df["sequence_a"].map(lr).to_numpy()
    rb = df["sequence_b"].map(lr).to_numpy()
    m = ra != rb
    if not m.any():
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    return float(np.mean(np.where(ra[m] < rb[m], c, 1 - c)))

# name: same_side_as_previous
# description: Rate at which a participant picks the same side (left/right) as on their previous trial; observed above null means sequential response perseveration the model (static side bias only) under-produces, below means alternation of sides it does not capture.
def test_statistic(df):
    d = df.sort_values(["participant_id", "trial_index"])
    c = d["chose_left"].to_numpy()
    p = d["participant_id"].to_numpy()
    same_p = p[1:] == p[:-1]
    if not same_p.any():
        return 0.5
    return float(np.mean((c[1:] == c[:-1])[same_p]))

# name: perfect_alternation_chosen
# description: Among pairs where exactly one sequence (length >= 3) perfectly alternates (HTHT..), the rate it is chosen as more random; observed below null means the model over-predicts choosing pure alternations, above means it under-predicts.
def test_statistic(df):
    def alt(s):
        n = s.str.len()
        return (n >= 3) & ~s.str.contains("HH") & ~s.str.contains("TT")
    aa, ab = alt(df["sequence_a"]).to_numpy(), alt(df["sequence_b"]).to_numpy()
    m = aa != ab
    if not m.any():
        return 0.5
    c = df["chose_left"].to_numpy()[m]
    return float(np.mean(np.where(aa[m], c, 1 - c)))
